import javafx.application.Application;
import javafx.scene.Group;
import javafx.scene.Scene;
import javafx.scene.image.Image;
import javafx.scene.paint.PhongMaterial;
import javafx.scene.shape.MeshView;
import javafx.scene.shape.TriangleMesh;
import javafx.stage.Stage;

public class EqtSp extends Application {

    private static final int SZ = 128;
    private static final float R = 200;

    @Override
    public void start(Stage stg) {
        MeshView sph = mkSph();
        Group grp = new Group(sph);
        Scene scn = new Scene(grp, 800, 600, true);
        stg.setScene(scn);
        stg.show();
    }

    private MeshView mkSph() {
        TriangleMesh msh = new TriangleMesh();
        for (int y = 0; y <= SZ; y++) {
            float v = (float) y / SZ;
            double lat = Math.PI * (v - 0.5);
            for (int x = 0; x <= SZ; x++) {
                float u = (float) x / SZ;
                double lon = 2 * Math.PI * u;
                float xPos = (float) (R * Math.cos(lat) * Math.cos(lon));
                float yPos = (float) (R * Math.sin(lat));
                float zPos = (float) (R * Math.cos(lat) * Math.sin(lon));
                msh.getPoints().addAll(xPos, yPos, zPos);
                msh.getTexCoords().addAll(u, v);
            }
        }
        for (int y = 0; y < SZ; y++) {
            for (int x = 0; x < SZ; x++) {
                int p0 = y * (SZ + 1) + x;
                int p1 = p0 + 1;
                int p2 = p0 + SZ + 1;
                int p3 = p2 + 1;
                msh.getFaces().addAll(p0, p0, p2, p2, p1, p1);
                msh.getFaces().addAll(p1, p1, p2, p2, p3, p3);
            }
        }
        MeshView vw = new MeshView(msh);
        PhongMaterial mat = new PhongMaterial();
        mat.setDiffuseMap(new Image(EqtSp.class.getResourceAsStream("/images/earth2.jpg")));
        vw.setMaterial(mat);
        return vw;
    }

    public static void main(String[] args) {
        launch(args);
    }
}
