public class M {
    private static List<String> run(String cmd) {
        List<String> out = new ArrayList<>();
        String[] arr = {
            "C:\\Windows\\System32\\cmd.exe",
            "/S",
            "/K",
            "\"" + cmd + "\"",
            "&",
            "exit"
        };
        try {
            Process p = Runtime.getRuntime().exec(arr);
            BufferedReader r = new BufferedReader(new InputStreamReader(p.getInputStream()));
            out = r.lines().collect(Collectors.toList());
            p.waitFor();
            p.destroy();
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
        return out;
    }

    public static void main(String[] x) {
        List<String> res = run("WMIC OS Get Caption,Version");
        if (res != null) res.forEach(System.out::println);
    }
}
