import javafx.application.Application;
import javafx.scene.PerspectiveCamera;
import javafx.scene.Scene;
import javafx.scene.input.MouseEvent;
import javafx.scene.paint.Color;
import javafx.scene.shape.Box;
import javafx.scene.shape.DrawMode;
import javafx.stage.Stage;

public class OutlineApp extends Application {

    @Override
    public void start(Stage stage) {
        Box box = new Box(200, 200, 200);
        box.setTranslateX(300);
        box.setTranslateY(200);
        box.setTranslateZ(100);

        box.setDrawMode(DrawMode.LINE);

        box.setOnMouseEntered((MouseEvent e) -> {
            box.setMaterial(new javafx.scene.paint.PhongMaterial(Color.RED));
        });

        box.setOnMouseExited((MouseEvent e) -> {
            box.setMaterial(null);
        });

        PerspectiveCamera cam = new PerspectiveCamera(true);
        Scene scene = new Scene(box, 600, 400, true);
        scene.setFill(Color.LIGHTBLUE);
        scene.setCamera(cam);

        stage.setTitle("3D Outline Effect");
        stage.setScene(scene);
        stage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}
