    List<String> hdr = new ArrayList<String>();
    List<HashMap<String, String>> tbl = new ArrayList<HashMap<String, String>>();

    String line = null;
    int ext = 0;
    while ((line = br.readLine()) != null) {
        if (ext == 0) {
            hdr = Arrays.asList(line.split(","));
        } else {
            HashMap<String, String> rec = new HashMap<String, String>();
