import numpy as np
from time import time

def cmp(do_cache: bool, arr_sz: int, n_arr: int, n_iter: int):
    arrs = {i: np.random.rand(arr_sz) for i in range(n_arr)}

    if do_cache:
        cache = {}

    for _ in range(n_iter):
        i, j = np.random.randint(n_arr, size=2)

        if do_cache and (i, j) in cache:
            _ = cache[(i, j)]
        else:
            _ = arrs[i] + arrs[j]
            if do_cache:
                cache[(i, j)] = _

%timeit cmp(do_cache=False, arr_sz=10000, n_arr=100, n_iter=1000)
%timeit cmp(do_cache=True, arr_sz=10000, n_arr=100, n_iter=1000)
,"[""import numpy as np\r\nfrom time import time\r\n\r\ndef cmp(do_cache: bool, arr_sz: int, n_arr: int, n_iter: int):\r\n    arrs = {i: np.random.rand(arr_sz) for i in range(n_arr)}\r\n\r\n    if do_cache:\r\n        cache = {}\r\n\r\n    for _ in range(n_iter):\r\n        i, j = np.random.randint(n_arr, size=2)\r\n\r\n        if do_cache and (i, j) in cache:\r\n            _ = cache[(i, j)]\r\n        else:\r\n            _ = arrs[i] + arrs[j]\r\n            if do_cache:\r\n                cache[(i, j)] = _\r\n\r\n%timeit cmp(do_cache=False, arr_sz=10000, n_arr=100, n_iter=1000)\r\n%timeit cmp(do_cache=True, arr_sz=10000, n_arr=100, n_iter=1000)\r\n""]",0

import concurrent.futures
import os
