from pydantic import BaseModel
class SFId(int):
    @classmethod
    def __get_validators__(cls):
        yield cls.validate

    @classmethod
    def validate(cls, v: str):
        return int(v)

    @classmethod
    def __modify_schema__(cls, field_schema: dict) -> None:
        field_schema['type'] = 'string'

class Mdl(BaseModel):
    id: SFId

    class Config:
        orm_mode = True
        arbitrary_types_allowed = True
        json_encoders = {
            SFId: lambda v: str(v)
        }
