import numpy as np
import pandas as pd

def check_overflow(lst, dtype):
    try:
        return pd.Series(lst, dtype=dtype)
    except OverflowError:
        raise ValueError(f"Overflow error for dtype {dtype}")

lst = [2**31-1]
ser = check_overflow(lst, 'int32')
ser = ser + 1

if ser.dtype == 'int32' and (ser < np.iinfo(np.int32).min or ser > np.iinfo(np.int32).max).any():
    raise ValueError("Overflow occurred after operation")
