from typing import Callable, TypeVar, Dict
from functools import wraps

T = TypeVar("T", bound=Callable[[int], int])

def remember(f: T) -> T:
    mem: Dict[int, int] = {}

    @wraps(f)
    def wrap(n: int) -> int:
        if n not in mem:
            mem[n] = f(n)
        return mem[n]

    return wrap  # type: ignore

@remember
def fib(n: int) -> int:
    if n < 2:
        return 1
    return fib(n - 2) + fib(n - 1)
,"[""from typing import Callable, TypeVar, Dict\r\nfrom functools import wraps\r\n\r\nT = TypeVar(""T"", bound=Callable[[int], int])\r\n\r\ndef remember(f: T) -> T:\r\n    mem: Dict[int, int] = {}\r\n\r\n    @wraps(f)\r\n    def wrap(n: int) -> int:\r\n        if n not in mem:\r\n            mem[n] = f(n)\r\n        return mem[n]\r\n\r\n    return wrap  # type: ignore\r\n\r\n@remember\r\ndef fib(n: int) -> int:\r\n    if n < 2:\r\n        return 1\r\n    return fib(n - 2) + fib(n - 1)\r\n""]",0

