class BST:
    def __init__(self, val):
        self.value = val
        self.left = None
        self.right = None

    def add(self, val):
        if self.value:
            if val < self.value:
                if self.left == None:
                    self.left = BST(val)
                else:
                    self.left.add(val)
            else:
                if val > self.value:
                    if self.right == None:
                        self.right = BST(val)
                    else:
                        self.right.add(val)
        else:
            self.value = val

    def traverse_pre(self, result=None):
        if result is None:
            result = []
        result.append(self.value)
        if self.left:
            self.left.traverse_pre(result)
        if self.right:
            self.right.traverse_pre(result)
        return result


tree = BST(5)
tree.add(10)
tree.add(8)
tree.add(2)
tree.add(4)
tree.add(7)

print(tree.traverse_pre())
,"[""class BST:\r\n    def __init__(self, val):\r\n        self.value = val\r\n        self.left = None\r\n        self.right = None\r\n\r\n    def add(self, val):\r\n        if self.value:\r\n            if val < self.value:\r\n                if self.left == None:\r\n                    self.left = BST(val)\r\n                else:\r\n                    self.left.add(val)\r\n            else:\r\n                if val > self.value:\r\n                    if self.right == None:\r\n                        self.right = BST(val)\r\n                    else:\r\n                        self.right.add(val)\r\n        else:\r\n            self.value = val\r\n\r\n    def traverse_pre(self, result=None):\r\n        if result is None:\r\n            result = []\r\n        result.append(self.value)\r\n        if self.left:\r\n            self.left.traverse_pre(result)\r\n        if self.right:\r\n            self.right.traverse_pre(result)\r\n        return result\r\n\r\n\r\ntree = BST(5)\r\ntree.add(10)\r\ntree.add(8)\r\ntree.add(2)\r\ntree.add(4)\r\ntree.add(7)\r\n\r\nprint(tree.traverse_pre())\r\n""]",0

