      //A character is considered as duplicate if count is greater than 1
      if(count > 1 && string[i] != '0') {
        System.out.println(string[i]);

        //here is flag updated if duplicates are found
        noDuplicates = false;
      }
    }

    //here is flag check
    if (noDuplicates) {
      System.out.println("no duplicates");
    }
