public class StreamProcessorInitializer 
    implements ApplicationContextInitializer<GenericWebApplicationContext> {

    @Override
    public void initialize(GenericWebApplicationContext context) {
        String functionDefinitions = context.getEnvironment()
            .getProperty("spring.cloud.function.definition");
        String splitter = context.getEnvironment()
            .getProperty("spring.cloud.function.definition.splitter");
        String factoryName = CaseFormat.UPPER_CAMEL.
            .to(CaseFormat.LOWER_CAMEL, MyFunctionDefinitionFactory.class.getSimpleName());
        String factoryMethodName =
             MyFunctionDefinitionFactory.class.getMethods()[0].getName();

        AnnotatedGenericBeanDefinition def = 
            new AnnotatedGenericBeanDefinition(Myfunctiondefinition.class);
        def.setFactoryBeanName(factoryName);
        def.setFactoryMethodName(factoryMethodName);

        Arrays.stream(functionDefinitions.split(splitter))
           .forEach(function -> context.registerBeanDefinition(function, def));
    }
},"[""// Behaves as dummy bean for spring cloud stream\r\n// Has to be the same name as the original streaming function in the factory.\r\n// In this case we named the method ""myfunctiondefinition"",\r\n// so the dummy-bean has to get the name ""Myfunctiondefinition"".\r\npublic class Myfunctiondefinition implements Function<KStream<String, InputType>, \r\n                KStream<String, OutputType>> {\r\n\r\n    // !!! It could be that changes are needed if spring cloud streams changes the logic\r\n    // Method myfunctiondefinition() is needed, because spring cloud streams searches for \r\n    // a method with the same name as the class in \r\n    // FunctionDetectorCondition:pruneFunctionBeansForKafkaStreams\r\n    public Function<KStream<String, InputType>, \r\n               KStream<String, OutputType>> myfunctiondefinition() {\r\n        return null

