        return None

from fastapi import FastAPI
from enum import Enum


app = FastAPI()


class CaseInsensitiveEnum(str, Enum):
    @classmethod
    def _missing_(cls, value):
        value = value.lower()
        for member in cls:
            if member.lower() == value:
                return member
        return None


class MyEnum(CaseInsensitiveEnum):
    ab = 'aB'
    cd = 'Cd'


@app.get("/")
def main(q: MyEnum):
    return q

